&lt;span id=&#34;cb5-31&#34;&gt;&lt;a href=&#34;#cb5-31&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;                q&lt;span class=&#34;op&#34;&gt;.&lt;/span&gt;resize&lt;span class=&#34;op&#34;&gt;(++&lt;/span&gt;t &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;),&lt;/span&gt; q&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;t&lt;span class=&#34;op&#34;&gt;]&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;=&lt;/span&gt; j&lt;span class=&#34;op&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
