&lt;span id=&#34;cb6-48&#34;&gt;&lt;a href=&#34;#cb6-48&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;            &lt;span class=&#34;cf&#34;&gt;for&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(;&lt;/span&gt; h &lt;span class=&#34;op&#34;&gt;&amp;lt;&lt;/span&gt; t &lt;span class=&#34;op&#34;&gt;&amp;amp;&amp;amp;&lt;/span&gt; f1&lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;p&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;q&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;h &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;]],&lt;/span&gt; p&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;q&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;h&lt;span class=&#34;op&#34;&gt;]])&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;lt;&lt;/span&gt; j &lt;span class=&#34;op&#34;&gt;*&lt;/span&gt; f2&lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;p&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;q&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;h &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;]],&lt;/span&gt; p&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;q&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;h&lt;span class=&#34;op&#34;&gt;]]);&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;++&lt;/span&gt;h&lt;span class=&#34;op&#34;&gt;);&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb6-49&#34;&gt;&lt;a href=&#34;#cb6-49&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;            res &lt;span class=&#34;op&#34;&gt;+=&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;p&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;q&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;h&lt;span class=&#34;op&#34;&gt;]].&lt;/span&gt;x &lt;span class=&#34;op&#34;&gt;-&lt;/span&gt; i&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;*&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;p&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;q&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;h&lt;span class=&#34;op&#34;&gt;]].&lt;/span&gt;x &lt;span class=&#34;op&#34;&gt;-&lt;/span&gt; i&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;p&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;q&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;h&lt;span class=&#34;op&#34;&gt;]].&lt;/span&gt;y &lt;span class=&#34;op&#34;&gt;-&lt;/span&gt; j&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;*&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;p&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;q&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;h&lt;span class=&#34;op&#34;&gt;]].&lt;/span&gt;y &lt;span class=&#34;op&#34;&gt;-&lt;/span&gt; j&lt;span class=&#34;op&#34;&gt;);&lt;/span&gt;&lt;/span&gt;
